<?php require_once __DIR__.'/../config/db.php'; require_role('usuario');$id=(int)($_GET['id']??$_POST['activity_id']??0);$s=$pdo->prepare('SELECT * FROM activities WHERE id=?');$s->execute([$id]);$activity=$s->fetch();if(!$activity){header('Location: actividades.php');exit;}$s=$pdo->prepare('SELECT * FROM questions WHERE activity_id=? ORDER BY id');$s->execute([$id]);$questions=$s->fetchAll();$score=null;
if($_SERVER['REQUEST_METHOD']==='POST' && $questions){$score=0;foreach($questions as $q){if(($_POST['answers'][$q['id']]??'')===$q['correct_option'])$score++;}$pdo->prepare('INSERT INTO results(user_id,activity_id,score,total) VALUES(?,?,?,?)')->execute([$_SESSION['user']['id'],$id,$score,count($questions)]);}
$pageTitle='Resolver actividad';require __DIR__.'/../partials/header.php'; ?><h1><?=e($activity['title'])?></h1><p><?=e($activity['description'])?></p><?php if($score!==null): ?><div class="success result-box">Resultado guardado: <strong><?=$score?> de <?=count($questions)?></strong> (<?=count($questions)?round($score/count($questions)*100):0?>%).</div><a class="btn" href="actividades.php">Volver a actividades</a><?php elseif(!$questions): ?><div class="alert">Esta actividad todavía no tiene preguntas. Intenta más tarde.</div><?php else: ?><form class="panel" method="post"><input type="hidden" name="activity_id" value="<?=$id?>"><?php foreach($questions as $i=>$q): ?><fieldset><legend><?=($i+1)?>. <?=e($q['question'])?></legend><?php foreach(['a'=>'option_a','b'=>'option_b','c'=>'option_c'] as $letter=>$col): ?><label class="option"><input type="radio" name="answers[<?=$q['id']?>]" value="<?=$letter?>" required> <?=strtoupper($letter)?>. <?=e($q[$col])?></label><?php endforeach; ?></fieldset><?php endforeach; ?><button class="btn">Enviar respuestas</button></form><?php endif; ?><?php require __DIR__.'/../partials/footer.php'; ?>